#include <sstream>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    std::ostringstream stream;
    stream << 42;
    assert(stream.str() == "42");
    assert(stream.rdbuf() != nullptr);
    std::ostringstream other;
    other = std::move(stream);
    other.swap(stream);
    std::swap(other, stream);
    std::cout << "Checks passed\n";
}
